from collections import OrderedDict

class LRU:
    def __init__(self, cap): self.cap, self.d = cap, OrderedDict()
    def get(self, k):
        if k not in self.d: return None
        self.d.move_to_end(k)            # mutates shared state on a READ
        return self.d[k]
    def put(self, k, v):
        if k in self.d: self.d.move_to_end(k)
        self.d[k] = v
        if len(self.d) > self.cap: self.d.popitem(last=False)

# scan: for k in range(1_000_000): c.get(k)   -> working set fully evicted

# one reference bit per frame, one circular hand
def clock_evict(frames, hand):
    while True:
        f = frames[hand]
        if f.ref == 0:
            hand = (hand + 1) % len(frames)
            return f, hand          # evict this one
        f.ref = 0                   # second chance
        hand = (hand + 1) % len(frames)

# on a hit:  f.ref = 1     <- a single relaxed store, no lock, no list surgery

def get_user(uid):
    key = f"user:{uid}:v3"
    v = redis.get(key)
    if v is not None:
        return decode(v)
    row = db.query("SELECT * FROM users WHERE id = %s", uid)   # miss: read through
    redis.set(key, encode(row), ex=300 + random.randint(0, 60))
    return row

def update_user(uid, patch):
