// runs in a V8 isolate in the PoP: microsecond startup, no container, no cold VM
export default {
  async fetch(req, env) {
    const u = new URL(req.url);
    u.search = '';                      // normalise the cache key at the edge
    const cache = caches.default;
    let res = await cache.match(u);
    if (!res) {
      res = await fetch(u);             // one origin fetch, collapsed at the PoP
      await cache.put(u, res.clone());
    }
    const cc = req.headers.get('cf-ipcountry');   // personalise WITHOUT an origin hit
    return new Response(await res.text() + cc, res);
  }
